using MiniPharmacie.Business.Models;
using MiniPharmacie.Business.Services;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Tests;

public sealed class SalesAndCashTests
{
    private static async Task<(DatabaseInitializer Db,StockManagementService Stock,SalesAndCashService Service,long User,long Product,long Supplier)> Setup(){var db=new DatabaseInitializer(Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db"));await db.InitializeAsync();await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO Roles(Name) VALUES('Responsable'),('Vendeur');INSERT INTO Users(RoleId,Username,PasswordHash,CreatedAt) VALUES(1,'manager','x',datetime('now')),(2,'cashier','x',datetime('now'));INSERT INTO Products(Code,Name,Unit,SalePriceMinor,ReorderLevel) VALUES('P1','Boîte','boîte',250,0);INSERT INTO Suppliers(Name) VALUES('Fournisseur');";await q.ExecuteNonQueryAsync();return(db,new(db),new(db),2,1,1);}
    // Les données de test créent l'utilisateur 1 comme responsable et l'utilisateur 2 comme vendeur.
    // La réception est une opération protégée: elle doit être préparée par le responsable.
    private static async Task<long> SeedStock(DatabaseInitializer db,StockManagementService stock,long user,long product,long supplier,int quantity){return await stock.ReceiveAsync(new(supplier,1,$"R-{Guid.NewGuid():N}",DateTimeOffset.Now,[new(product,quantity,100,$"LOT-{Guid.NewGuid():N}",DateOnly.FromDateTime(DateTime.Today.AddDays(200)))],null));}
    [Fact] public async Task SellsThreeOfTwentyAndKeepsSeventeen(){var(db,stock,s,u,p,v)=await Setup();await SeedStock(db,stock,u,p,v,20);var session=await s.OpenCashSessionAsync(u,1000);var sale=await s.CheckoutAsync(new(u,session,[new(p,"P1","Boîte",250,3)],[new("ESPECES",750)]));Assert.True(sale>0);Assert.Equal(17,(await stock.GetProductsAsync()).Single().Physical);}
    [Fact] public async Task InsufficientStockRollsBackSalePaymentAndMovement(){var(db,stock,s,u,p,v)=await Setup();await SeedStock(db,stock,u,p,v,2);var session=await s.OpenCashSessionAsync(u,0);await Assert.ThrowsAsync<InvalidOperationException>(()=>s.CheckoutAsync(new(u,session,[new(p,"P1","Boîte",250,3)],[new("ESPECES",750)])));await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT (SELECT COUNT(*) FROM Sales)+(SELECT COUNT(*) FROM Payments)+(SELECT COUNT(*) FROM SaleLines)";Assert.Equal(0L,(long)(await q.ExecuteScalarAsync())!);}
    [Fact] public async Task ExpiredOrBlockedLotCannotBeSold(){var(db,stock,s,u,p,v)=await Setup();await stock.ReceiveAsync(new(v,1,"R-exp",DateTimeOffset.Now,[new(p,2,100,"EXP",DateOnly.FromDateTime(DateTime.Today.AddDays(-1)))],null));await stock.ReceiveAsync(new(v,1,"R-blk",DateTimeOffset.Now,[new(p,2,100,"BLK",DateOnly.FromDateTime(DateTime.Today.AddDays(30)))],null));await using(var c=db.CreateConnection()){await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="UPDATE Lots SET IsBlocked=1 WHERE LotNumber='BLK'";await q.ExecuteNonQueryAsync();}var session=await s.OpenCashSessionAsync(u,0);await Assert.ThrowsAsync<InvalidOperationException>(()=>s.CheckoutAsync(new(u,session,[new(p,"P1","Boîte",250,1)],[new("ESPECES",250)])));}
    [Fact] public async Task DiscountAndCancellationAreManagerOnly(){var(db,stock,s,u,p,v)=await Setup();await SeedStock(db,stock,u,p,v,4);var session=await s.OpenCashSessionAsync(u,0);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>s.CheckoutAsync(new(u,session,[new(p,"P1","Boîte",250,1)],[new("ESPECES",200)],50)));var sale=await s.CheckoutAsync(new(1,session,[new(p,"P1","Boîte",250,1)],[new("ESPECES",250)]));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>s.ReverseSaleAsync(sale,u,"ANNULATION","erreur",250));}
    [Fact] public async Task ReturnCreatesBlockedCompensatingStockAndCannotExceedSoldQuantity(){var(db,stock,s,u,p,v)=await Setup();await SeedStock(db,stock,u,p,v,4);var session=await s.OpenCashSessionAsync(u,0);var sale=await s.CheckoutAsync(new(u,session,[new(p,"P1","Boîte",250,2)],[new("ESPECES",500)]));await s.ReverseSaleAsync(sale,1,"RETOUR","Client",500);Assert.Equal(2,(await stock.GetProductsAsync()).Single().Sellable);await Assert.ThrowsAsync<Microsoft.Data.Sqlite.SqliteException>(()=>s.ReverseSaleAsync(sale,1,"RETOUR","Deuxième retour",500));}
    [Fact] public async Task TicketCanBeReadAgainAndCheckoutRetryIsIdempotent(){var(db,stock,s,u,p,v)=await Setup();await SeedStock(db,stock,u,p,v,3);var session=await s.OpenCashSessionAsync(u,0);var draft=new SaleDraft(u,session,[new(p,"P1","Boîte",250,1)],[new("ESPECES",250)],0,"request-one");var id=await s.CheckoutAsync(draft);var first=await s.GetReceiptAsync(id);var second=await s.GetReceiptAsync(id);Assert.Equal(first.Number,second.Number);Assert.Equal(id,await s.CheckoutAsync(draft));await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM Sales";Assert.Equal(1L,(long)(await q.ExecuteScalarAsync())!);}
    [Fact] public async Task CashCloseRecordsExpectedAndDifference(){var(db,stock,s,u,p,v)=await Setup();await SeedStock(db,stock,u,p,v,5);var session=await s.OpenCashSessionAsync(u,1000);await s.CheckoutAsync(new(u,session,[new(p,"P1","Boîte",250,2)],[new("ESPECES",500)]));await s.AddCashMovementAsync(session,u,"SORTIE",100,"Dépense");await s.CloseCashSessionAsync(session,u,1300);await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT ExpectedCashMinor,DifferenceMinor FROM CashSessionClosures WHERE SessionId=$s";q.Parameters.AddWithValue("$s",session);await using var r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());Assert.Equal(1400L,r.GetInt64(0));Assert.Equal(-100L,r.GetInt64(1));}
}
